import { ResourceAllocationData } from '../types';

export const hasPublicisChartEntry = (
  entry?: ResourceAllocationData,
): boolean => {
  if (!entry || entry.empty) {
    return false;
  }

  const chart = entry.total_per_year_full;

  if (!chart) {
    return false;
  }

  const hasLabels = Array.isArray(chart.labels) && chart.labels.length > 0;
  const hasDatasets =
    Array.isArray(chart.datasets) &&
    chart.datasets.some(
      (dataset) => Array.isArray(dataset.data) && dataset.data.length > 0,
    );

  return hasLabels && hasDatasets;
};
